// SPDX-License-Identifier: MIT
// Prismcairn Duel (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/prismcairn.py (prism-shard-dev), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "prismcairn:<seed>:<difficulty>"); the Warden's slip roll is drawn every turn, as in Python.
// Byte parity goes through engines/unreal/core-test/prismcairn_parity.txt (prismcairn_core_test.cpp), generated by
// tools/minigames/prismcairn_parity.py.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <string>
#include <utility>
#include <vector>

namespace daedalus { namespace prismcairn {

inline const char* GameId() { return "prismcairn"; }
inline const char* Title() { return "Prismcairn Duel"; }

struct Difficulty { const char* Name; int Cairns; int TakeMax; int MaxHeight; double Slip; int Rounds; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 3, 3, 7, 0.5, 3 }, { "normal", 4, 3, 9, 0.25, 3 }, { "hard", 5, 4, 11, 0.0, 3 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

inline int Grundy(const std::vector<int>& Cairns, int TakeMax) { int G = 0; for (int H : Cairns) G ^= H % (TakeMax + 1); return G; }

/** prismcairn.best_move: a move to a zero position if one exists, else the smallest legal move. */
inline std::pair<int, int> BestMove(const std::vector<int>& Cairns, int TakeMax)
{
	for (int I = 0; I < static_cast<int>(Cairns.size()); ++I)
		for (int T = 1; T <= std::min(TakeMax, Cairns[static_cast<size_t>(I)]); ++T)
		{
			std::vector<int> Next = Cairns; Next[static_cast<size_t>(I)] -= T;
			if (Grundy(Next, TakeMax) == 0) return { I, T };
		}
	for (int I = 0; I < static_cast<int>(Cairns.size()); ++I) if (Cairns[static_cast<size_t>(I)]) return { I, 1 };
	return { 0, 1 };
}

struct LogRow { int YouCairn, YouTake; bool RoundEnd; bool Warden; int WardenCairn, WardenTake; };

struct Game
{
	const Difficulty* Diff = nullptr;
	int Round = 0, Wins = 0, Losses = 0;
	std::vector<int> Cairns;
	std::vector<LogRow> Log;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	int RandInt(int A, int B) { return A + static_cast<int>(Rng.Below(static_cast<std::uint32_t>(B - A + 1))); }
	bool AnyShards() const { for (int H : Cairns) if (H) return true; return false; }

	void Deal()
	{
		++Round;
		while (true)
		{
			std::vector<int> C;
			for (int I = 0; I < Diff->Cairns; ++I) C.push_back(RandInt(1, Diff->MaxHeight));
			if (Grundy(C, Diff->TakeMax)) { Cairns = C; break; }
		}
	}

	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		Round = Wins = Losses = 0; Log.clear();
		Deal();
		return true;
	}

	void RoundOver(bool PlayerWon)
	{
		if (PlayerWon) { ++Wins; Score += 50; } else ++Losses;
		const int Need = Diff->Rounds / 2 + 1;
		if (Wins >= Need) { Score += 5 * (Diff->Rounds - Round); Over = true; Won = true; }
		else if (Losses >= Need) { Over = true; Won = false; }
		else Deal();
	}

	enum class Act : int { Ok = 0, GameOver, BadMove };
	enum class Outcome : int { YouLiftLast = 0, WardenTakes, WardenLiftsLast };

	/** Mirrors prismcairn.Game.act. Outcome + the Warden's reply (cairn, take) when it moved. */
	Act Take(int I, int T, Outcome& Out, int& WardenCairn, int& WardenTake)
	{
		Out = Outcome::WardenTakes; WardenCairn = WardenTake = -1;
		if (Over) return Act::GameOver;
		const int N = static_cast<int>(Cairns.size());
		if (I < 0 || I >= N || T < 1 || T > std::min(Diff->TakeMax, Cairns[static_cast<size_t>(I)])) return Act::BadMove;
		Cairns[static_cast<size_t>(I)] -= T;
		if (!AnyShards()) { Log.push_back({ I, T, true, false, 0, 0 }); RoundOver(true); Out = Outcome::YouLiftLast; return Act::Ok; }
		std::pair<int, int> W;
		if (Rng.RandomDouble() < Diff->Slip)
		{
			std::vector<int> NonEmpty; for (int X = 0; X < N; ++X) if (Cairns[static_cast<size_t>(X)]) NonEmpty.push_back(X);
			const int J = NonEmpty[Rng.ChoiceIndex(NonEmpty.size())];
			W = { J, RandInt(1, std::min(Diff->TakeMax, Cairns[static_cast<size_t>(J)])) };
		}
		else W = BestMove(Cairns, Diff->TakeMax);
		Cairns[static_cast<size_t>(W.first)] -= W.second;
		Log.push_back({ I, T, false, true, W.first, W.second });
		WardenCairn = W.first; WardenTake = W.second;
		if (!AnyShards()) { RoundOver(false); Out = Outcome::WardenLiftsLast; return Act::Ok; }
		Out = Outcome::WardenTakes;
		return Act::Ok;
	}

	std::pair<int, int> DemoAction() const { return BestMove(Cairns, Diff->TakeMax); }
	std::string CairnsString() const { std::string S; for (size_t I = 0; I < Cairns.size(); ++I) { if (I) S.push_back(','); S += std::to_string(Cairns[I]); } return S; }
};

} } // namespace daedalus::prismcairn
